record Item(String sku, String name, int quantity, long priceCents) {
    Item {
        if (sku == null || !sku.matches("[A-Za-z0-9-]{3,12}")) throw new IllegalArgumentException("bad sku " + sku);
        if (name == null || name.isBlank()) throw new IllegalArgumentException("blank name");
        if (quantity < 0) throw new IllegalArgumentException("negative quantity");
        if (priceCents < 0) throw new IllegalArgumentException("negative price");
        sku = sku.toUpperCase();
        name = name.trim();
    }

    long valueCents() { return quantity * priceCents; }
}

solution.InventoryException.java:
class InventoryException extends Exception {
    private final int line;

    InventoryException(int line, String message) {
        this(line, message, null);
    }

    InventoryException(int line, String message, Throwable cause) {
        super("line " + line + ": " + message, cause);
        this.line = line;
    }

    int line() { return line; }
}

solution.Inventory.java:
import java.io.*;
import java.nio.file.*;
import java.util.*;

class Inventory {
    private static final String HEADER = "sku,name,quantity,price";
    private final Map<String, Item> items = new HashMap<>();

    void add(Item item) {
        if (items.containsKey(item.sku())) throw new IllegalArgumentException("duplicate sku " + item.sku());
        items.put(item.sku(), item);
    }

    Item find(String sku) { return items.get(sku.toUpperCase()); }

    private Item require(String sku) {
        Item item = find(sku);
        if (item == null) throw new NoSuchElementException("no item " + sku);
        return item;
    }

    void restock(String sku, int amount) {
        if (amount < 1) throw new IllegalArgumentException("amount must be at least 1");
        Item item = require(sku);
        items.put(item.sku(), new Item(item.sku(), item.name(), item.quantity() + amount, item.priceCents()));
    }

    void sell(String sku, int amount) {
        if (amount < 1) throw new IllegalArgumentException("amount must be at least 1");
        Item item = require(sku);
        if (item.quantity() < amount) throw new IllegalStateException("only " + item.quantity() + " left");
        items.put(item.sku(), new Item(item.sku(), item.name(), item.quantity() - amount, item.priceCents()));
    }

    long totalValueCents() {
        long total = 0;
        for (Item item : items.values()) total += item.valueCents();
        return total;
    }

    List<Item> all() {
        List<Item> list = new ArrayList<>(items.values());
        list.sort(Comparator.comparing(Item::sku));
        return list;
    }

    List<Item> lowStock(int threshold) {
        List<Item> list = new ArrayList<>();
        for (Item item : items.values()) if (item.quantity() < threshold) list.add(item);
        list.sort(Comparator.comparingInt(Item::quantity).thenComparing(Item::sku));
        return list;
    }

    List<Item> search(String term) {
        String t = term.toLowerCase();
        List<Item> list = new ArrayList<>();
        for (Item item : items.values()) if (item.name().toLowerCase().contains(t)) list.add(item);
        list.sort(Comparator.comparing(Item::name).thenComparing(Item::sku));
        return list;
    }

    private static String euros(long cents) { return String.format("%d.%02d", cents / 100, cents % 100); }

    void save(Path file) throws IOException {
        if (file.getParent() != null) Files.createDirectories(file.getParent());
        try (BufferedWriter out = Files.newBufferedWriter(file)) {
            out.write(HEADER);
            out.newLine();
            for (Item item : all()) {
                out.write(item.sku() + "," + item.name() + "," + item.quantity() + "," + euros(item.priceCents()));
                out.newLine();
            }
        }
    }

    static Inventory load(Path file) throws IOException, InventoryException {
        List<String> lines = Files.readAllLines(file);
        if (lines.isEmpty() || !lines.get(0).trim().equals(HEADER)) throw new InventoryException(1, "bad header");
        Inventory inv = new Inventory();
        for (int i = 1; i < lines.size(); i++) {
            int n = i + 1;
            String line = lines.get(i);
            if (line.isBlank()) continue;
            String[] f = line.split(",", -1);
            if (f.length != 4) throw new InventoryException(n, "wrong number of fields");
            int quantity;
            long cents;
            try {
                quantity = Integer.parseInt(f[2].trim());
                cents = Math.round(Double.parseDouble(f[3].trim()) * 100);
            } catch (NumberFormatException e) {
                throw new InventoryException(n, "bad number", e);
            }
            Item item;
            try {
                item = new Item(f[0].trim(), f[1], quantity, cents);
            } catch (IllegalArgumentException e) {
                throw new InventoryException(n, e.getMessage(), e);
            }
            if (inv.items.containsKey(item.sku())) throw new InventoryException(n, "duplicate sku " + item.sku());
            inv.add(item);
        }
        return inv;
    }
}

unitTests:
Supplier<Inventory> shop = () -> {
    Inventory inv = new Inventory();
    inv.add(new Item("tea-01", " Green tea ", 40, 250));
    inv.add(new Item("MUG-01", "Large mug", 3, 800));
    inv.add(new Item("MUG-02", "Small mug", 3, 650));
    inv.add(new Item("PEN-9", "Pen", 0, 120));
    return inv;
};
Function<Path, String> loadError = p -> {
    try { Inventory.load(p); return "no error"; }
    catch (InventoryException e) { return e.getMessage(); }
    catch (IOException e) { return "io: " + e.getClass().getSimpleName(); }
};

test("items validate and normalise", () -> {
    Item t = new Item("tea-01", " Green tea ", 40, 250);
    checkEq(t, new Item("TEA-01", "Green tea", 40, 250));
    for (Runnable bad : List.<Runnable>of(
            () -> new Item("ab", "x", 1, 1), () -> new Item("bad sku!", "x", 1, 1),
            () -> new Item("ABC", " ", 1, 1), () -> new Item("ABC", "x", -1, 1), () -> new Item("ABC", "x", 1, -1))) {
        checkThrows(IllegalArgumentException.class, bad::run);
    }
});

test("stock operations", () -> {
    Inventory inv = shop.get();
    checkEq(inv.find("tea-01").quantity(), 40);
    checkEq(inv.find("nope"), null);
    inv.sell("TEA-01", 15);
    inv.restock("pen-9", 10);
    checkEq(inv.find("TEA-01").quantity(), 25);
    checkEq(inv.find("PEN-9").quantity(), 10);
    try { inv.sell("MUG-01", 4); check(false, "should throw"); }
    catch (IllegalStateException e) { checkEq(e.getMessage(), "only 3 left"); }
    try { inv.restock("XYZ-1", 1); check(false, "should throw"); }
    catch (NoSuchElementException e) { checkEq(e.getMessage(), "no item XYZ-1"); }
    checkThrows(IllegalArgumentException.class, () -> inv.sell("TEA-01", 0));
    checkThrows(IllegalArgumentException.class, () -> inv.add(new Item("Mug-01", "Copy", 1, 1)));
    checkEq(inv.totalValueCents(), 25L * 250 + 3 * 800 + 3 * 650 + 10 * 120);
});

test("reports", () -> {
    Inventory inv = shop.get();
    checkEq(inv.lowStock(5).stream().map(Item::sku).toList(), List.of("PEN-9", "MUG-01", "MUG-02"));
    checkEq(inv.search("MUG").stream().map(Item::name).toList(), List.of("Large mug", "Small mug"));
    checkEq(inv.search("e").stream().map(Item::sku).toList(), List.of("TEA-01", "MUG-01", "PEN-9"));
    checkEq(inv.all().stream().map(Item::sku).toList(), List.of("MUG-01", "MUG-02", "PEN-9", "TEA-01"));
});

test("saving and loading", () -> {
    Path dir = Files.createTempDirectory("xenon-inv");
    Path file = dir.resolve("data/stock.csv");
    shop.get().save(file);
    checkEq(Files.readAllLines(file), List.of("sku,name,quantity,price", "MUG-01,Large mug,3,8.00", "MUG-02,Small mug,3,6.50",
                                              "PEN-9,Pen,0,1.20", "TEA-01,Green tea,40,2.50"));
    Inventory back = Inventory.load(file);
    checkEq(back.all(), shop.get().all());
});

test("bad files", () -> {
    Path dir = Files.createTempDirectory("xenon-inv");
    String[][] cases = {
        {"name,sku,quantity,price\n", "line 1: bad header"},
        {"sku,name,quantity,price\nTEA-01,Tea,4\n", "line 2: wrong number of fields"},
        {"sku,name,quantity,price\n\nTEA-01,Tea,four,2.50\n", "line 3: bad number"},
        {"sku,name,quantity,price\nTEA-01,Tea,-4,2.50\n", "line 2: negative quantity"},
        {"sku,name,quantity,price\nTEA-01,Tea,4,2.50\ntea-01,Other,1,1.00\n", "line 3: duplicate sku TEA-01"},
    };
    for (String[] c : cases) {
        Path f = dir.resolve("bad.csv");
        Files.writeString(f, c[0]);
        checkEq(loadError.apply(f), c[1]);
    }
    Files.writeString(dir.resolve("num.csv"), "sku,name,quantity,price\nTEA-01,Tea,4,x\n");
    try { Inventory.load(dir.resolve("num.csv")); check(false, "should throw"); }
    catch (InventoryException e) { check(e.getCause() instanceof NumberFormatException, "keep the cause"); checkEq(e.line(), 2); }
    checkEq(loadError.apply(dir.resolve("missing.csv")), "io: NoSuchFileException");
});

